locations=[]
def loc(id,name,faction,owner,description,refs,confidence='reconstruction',note='',**extra):
 c=COORD[id]
 record={'id':id,'name':name,**c,'faction':faction,'owner':owner,'description':description,'objects':[],
  'provenance':{'confidence':confidence,'sources':refs,'chronology':'После Второй войны, до выхода Гилнеаса из Альянса и сооружения стены.',
  'note':note or ('Место описано в более поздней географии. Непрерывность до стены и частный владелец не подтверждены; показано как реконструкция.' if confidence=='reconstruction' else '')}}
 record.update(extra);locations.append(record)

loc('gilneas-city','Город Гилнеас','greymane','Генн Седогрив','Столица королевства и средоточие власти Седогривов. Двор и улицы ещё принадлежат человеческому Гилнеасу; дороги к северным владениям открыты.',[7,5],'confirmed',subtitle='Столица человеческого королевства')
loc('greymane-manor','Поместье Седогрива','greymane','Генн Седогрив','Резиденция королевской семьи высоко в западных холмах. Отсюда открывается вид на прибрежные земли и поселения у моря.',[3,7],'reconstruction','Семейная принадлежность подтверждена; положение на современной подложке и непрерывность конкретных строений до стены — реконструкция.')
